// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 burn) public {
        vm.assume(amount > 0 && amount < address(this).balance);
        burn = bound(burn, 0, 500);
        GreedyReceiver r = new GreedyReceiver();
        r.setBurn(burn);
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(r), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract GreedyReceiver {
    uint256 public burn;
    function setBurn(uint256 b) external { burn = b; }
    receive() external payable {
        uint256 s = 0;
        for (uint256 i = 0; i < burn; i++) { s += i * i; }
        if (s == type(uint256).max) revert();
    }
}
